import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"预览工程页面","description":"查看工程开发页面，区分刷新、重启与停止，切换预览身份并使用独立窗口。","frontmatter":{"title":"预览工程页面","description":"查看工程开发页面，区分刷新、重启与停止，切换预览身份并使用独立窗口。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/preview.md","filePath":"zh/使用指南/预览工程页面.md"}'),o={name:"zh/guide/preview.md"};function h(n,t,i,s,l,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="预览工程页面" tabindex="-1">预览工程页面 <a class="header-anchor" href="#预览工程页面" aria-label="Permalink to &quot;预览工程页面&quot;">​</a></h1><p>预览用于检查正在开发的工程页面。它不是已经部署的正式运行入口，也不会仅因画面显示正常就自动完成发布。</p><p>从工程“应用开发”打开 <strong>“页面”</strong>，先确保开发环境和工程源码已准备好。首次操作见<a href="/induframe-docs/zh/guide/workspace.html">使用应用开发工作区</a>。</p><h2 id="_1-让预览显示出来" tabindex="-1">1. 让预览显示出来 <a class="header-anchor" href="#_1-让预览显示出来" aria-label="Permalink to &quot;1. 让预览显示出来&quot;">​</a></h2><p>等待预览服务就绪；如果页面提供 <strong>“启动预览”</strong>，点击后等待启动与连接完成。</p><p>持续显示错误时，保留提示，先检查开发环境和预览服务状态。不要自己拼接本机端口或复制临时内部地址代替平台入口。</p><h2 id="_2-分清刷新、重启和停止" tabindex="-1">2. 分清刷新、重启和停止 <a class="header-anchor" href="#_2-分清刷新、重启和停止" aria-label="Permalink to &quot;2. 分清刷新、重启和停止&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>影响</th></tr></thead><tbody><tr><td>刷新</td><td>只重新加载预览画面，不重启预览服务</td></tr><tr><td>重启</td><td>重新启动预览服务，页面随后重新加载</td></tr><tr><td>停止预览服务</td><td>暂停预览进程，不等于停止整个工程开发环境</td></tr><tr><td>停止开发环境</td><td>AI、编辑器和预览一起暂停，影响共同使用者</td></tr></tbody></table><p>刚保存普通页面修改时，可先查看当前预览或使用“刷新”。需要重启开发进程时才使用“重启”，不要连续操作使状态更难判断。</p><h2 id="_3-调整查看方式" tabindex="-1">3. 调整查看方式 <a class="header-anchor" href="#_3-调整查看方式" aria-label="Permalink to &quot;3. 调整查看方式&quot;">​</a></h2><p>可用工具栏切换预览设备、缩放画面或进入全屏。模拟不同画面尺寸便于检查排版，仍需另外在实际目标设备上核对使用效果。</p><p>需要单独查看时，使用 <strong>“在新窗口打开”</strong>。独立窗口仍要求相应访问权限；开发服务停止时，应回到工作区启动，不把新窗口当作另一套独立服务。</p><h2 id="_4-页面要求工程用户登录时" tabindex="-1">4. 页面要求工程用户登录时 <a class="header-anchor" href="#_4-页面要求工程用户登录时" aria-label="Permalink to &quot;4. 页面要求工程用户登录时&quot;">​</a></h2><p>组织账号用于进入平台，工程用户用于工程页面自己的登录与数据权限，两者不同。</p><p>有权限的开发人员可使用 **“以工程用户预览”**或预览身份选择器，按某个工程用户查看页面。切换身份后，重新核对画面及可读写内容；不要把这种开发辅助操作当成已经验证了真实用户的密码登录。</p><p>新工程的初始管理员口令不会直接展示。需要测试页面自身登录时，可按界面使用 <strong>“设置管理员口令”</strong>，输入自己的口令再测试；也可按权限选择合适的预览身份。</p><p>结束时可使用 <strong>“退出预览登录”</strong>。它处理工程页面的预览身份，不等于退出组织工作台。</p><h2 id="_5-预览与正式运行分开确认" tabindex="-1">5. 预览与正式运行分开确认 <a class="header-anchor" href="#_5-预览与正式运行分开确认" aria-label="Permalink to &quot;5. 预览与正式运行分开确认&quot;">​</a></h2><p>开发预览可使用正在修改的源码与开发配置。正式运行读取部署的工程版本，更新过程见<a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发、发布与运行</a>。</p><p>代码保存后能预览、某个身份能取数，都还需要按实际用途检查交互、数据权限和目标运行配置。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先检查什么</th></tr></thead><tbody><tr><td>一直启动或连接中</td><td>开发环境和预览服务状态，当前是否还有别的启停操作</td></tr><tr><td>画面没有更新</td><td>是否保存了源码，是否只需刷新页面</td></tr><tr><td>页面提示需要登录</td><td>当前工程用户或预览身份，不能直接套用组织账号</td></tr><tr><td>独立窗口不能继续</td><td>回到工作区确认服务和访问状态，必要时重新从平台打开</td></tr><tr><td>数据或权限不符合预期</td><td>核对当前工程与预览身份，再记录具体提示</td></tr></tbody></table><p>问题仍在时，保留时间、工程名称和提示交给维护人员，不通过删除工程、改浏览器安全配置或分享登录资料解决。</p>',23)])])}const u=a(o,[["render",h]]);export{c as __pageData,u as default};
